  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Biblical Stewardship and the Purpose of Money$j$, $j${"readings": [{"title": "Psalm 24 (King James Version)", "url": "/portal/bible/Psalms/24"}], "body": "Personal finance begins with a question of ownership. Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein. If everything belongs to God, then we are not owners but stewards. A steward is a person who manages what belongs to another. 1 Corinthians 4:2 says, Moreover it is required in stewards, that a man be found faithful.\n\nJesus taught this in the parable of the talents in Matthew 25. A master gave money to three servants and went away. Two servants put the money to work and returned more. The master said in verse 21, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things. The third servant buried his money and was called unprofitable. The lesson is that God expects us to use what we are given with wisdom and effort.\n\nMoney is a tool and not a master. It is useful for meeting needs, caring for family, giving to the work of God and helping people in need. It becomes a danger when it takes the place of God. 1 Timothy 6:10 says, For the love of money is the root of all evil: which while some coveted after, they have erred from the faith, and pierced themselves through with many sorrows. The verse warns about the love of money, not money itself.\n\nContentment protects the heart. Hebrews 13:5 says, Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee. Luke 12:15 adds, Take heed, and beware of covetousness: for a man's life consisteth not in the abundance of the things which he possesseth.\n\nA faithful steward does four things: earns honestly, spends wisely, saves for the future and gives generously.\n\nYour task: (1) Explain the difference between an owner and a steward. (2) Tell what the parable of the talents teaches. (3) Explain what 1 Timothy 6:10 warns against.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein. If everything belongs to God, then we are stewards, not owners. A steward manages what belongs to another. 1 Corinthians 4:2 says, it is required in stewards, that a man be found faithful.\n\nNow watch this. In Matthew 25 a master gave money to three servants. Two put it to work. The master said, Well done, thou good and faithful servant. The third buried his money. God expects us to use what we are given with wisdom and effort.\n\nMoney is a tool, not a master. 1 Timothy 6:10 warns about the love of money, not money itself. Hebrews 13:5 says, be content with such things as ye have. And Luke 12:15 says a man's life consisteth not in the abundance of the things which he possesseth.\n\nA faithful steward earns honestly, spends wisely, saves for the future and gives generously.\n\nYour task is to explain the steward, the talents and the warning about the love of money. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Biblical Stewardship and the Purpose of Money$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Needs, Wants, Goals and Choices$j$, $j${"readings": [{"title": "Luke 14 (King James Version)", "url": "/portal/bible/Luke/14"}], "body": "Every person has limited money and unlimited desires, so every person must make choices. A need is something required to live and function, such as food, clothing, shelter, basic transportation and health care. A want is something that is pleasant to have but not required, such as a game system, name brand shoes or a restaurant meal. Needs come first, and wants must be weighed carefully.\n\nEconomists use the term opportunity cost for the next best thing you give up when you make a choice. If you spend twenty dollars on a movie ticket, the opportunity cost might be the twenty dollars you could have saved or given. Thinking about opportunity cost helps a person see the true price of a decision.\n\nWise people set goals. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? A useful method is the SMART goal. A SMART goal is specific, measurable, achievable, realistic and set with a time limit. Instead of saying, I want to save money, say, I will save six hundred dollars in twelve months by setting aside fifty dollars each month.\n\nGoals come in three lengths. Short term goals take less than a year, such as buying a school item. Medium term goals take one to five years, such as saving for a car. Long term goals take more than five years, such as paying for college or buying a home. Write goals down, review them often and ask a parent, pastor or mentor for counsel. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nAdvertising works hard to turn wants into felt needs. Pause before buying, wait a day or more, and ask whether the purchase serves your goals.\n\nYour task: (1) Give three examples of needs and three of wants. (2) Define opportunity cost with an example. (3) Write one SMART goal.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? Wise people plan before they spend.\n\nNow watch this. A need is required to live, like food, clothing and shelter. A want is pleasant but not required. Needs come first.\n\nOpportunity cost is the next best thing you give up when you choose. Spend twenty dollars on a ticket and you give up saving or giving that twenty.\n\nSet SMART goals. Specific, measurable, achievable, realistic and timed. Not, I want to save money, but, I will save six hundred dollars in twelve months by setting aside fifty dollars each month.\n\nShort term goals take under a year. Medium term takes one to five years. Long term takes more than five. Write them down and seek counsel. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nAdvertising turns wants into felt needs. Pause a day before you buy.\n\nYour task is to list needs and wants, define opportunity cost and write a SMART goal. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Needs, Wants, Goals and Choices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Income, Work and Careers$j$, $j${"readings": [{"title": "Proverbs 14 (King James Version)", "url": "/portal/bible/Proverbs/14"}], "body": "Income is the money a person receives, usually from work. The Bible honors honest work. Proverbs 14:23 says, In all labour there is profit: but the talk of the lips tendeth only to penury. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. 2 Thessalonians 3:10 teaches, if any would not work, neither should he eat. Proverbs 10:4 adds, He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.\n\nIncome comes from several sources. Wages are paid by the hour. A salary is a fixed amount paid for a year of work. Commissions are payments based on sales. Tips are gifts from customers. Self employed people earn profit from their own business. Other sources include interest from savings, gifts and benefits. Income that is earned by work is called earned income.\n\nYour income is shaped by your skills, education, experience and the demand for your work. In general, people with more education and training earn more over a lifetime, though this is not guaranteed and training in a skilled trade can also lead to strong income. The cost of the training matters too, so compare the cost with the likely pay.\n\nCareers deserve research. Use sources such as the Occupational Outlook Handbook of the United States Bureau of Labor Statistics, which lists pay, training and job outlook. Ask people in the field about their day to day work. Think about your gifts, your interests and God's calling. A career is not only a paycheck but also a way to serve.\n\nGood work habits build income over time: being on time, honest, teachable and reliable. Employers notice. A first job, a skill, or a small business can teach responsibility. Young people should also protect their health, school and family life while working, and follow laws about hours and age for minors.\n\nYour task: (1) Name four kinds of income. (2) Explain how education and skills affect pay. (3) Describe how you would research a career.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. And Proverbs 10:4 says, the hand of the diligent maketh rich. The Bible honors honest work.\n\nNow watch this. Wages are paid by the hour. A salary is a fixed yearly amount. Commissions are based on sales. Tips come from customers. Self employed people earn profit from their own business. Other income includes interest and gifts.\n\nYour pay is shaped by skills, education, experience and demand. More training often means higher lifetime pay, though it is not guaranteed, and skilled trades can pay well. Compare the cost of training with likely pay.\n\nResearch careers. Use the Occupational Outlook Handbook from the Bureau of Labor Statistics. Talk to people in the field. Think about your gifts and God's calling. A career is also a way to serve.\n\nBe on time, honest, teachable and reliable. Protect your health, school and family while working.\n\nYour task is to name kinds of income, explain how education affects pay and describe how to research a career. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Income, Work and Careers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Paychecks, Taxes and Giving to Caesar$j$, $j${"readings": [{"title": "Romans 13 (King James Version)", "url": "/portal/bible/Romans/13"}], "body": "Many first time workers are surprised that a paycheck is smaller than expected. Gross pay is the total earned before anything is taken out. Net pay, often called take home pay, is what remains after deductions. Deductions include taxes and sometimes insurance or retirement contributions.\n\nTaxes pay for public services such as roads, schools, emergency services, defense and courts. Jesus said in Matthew 22:21, Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's. Paul wrote in Romans 13:7, Render therefore to all their dues: tribute to whom tribute is due; custom to whom custom; fear to whom fear; honour to whom honour. Honest taxpaying is part of good citizenship.\n\nCommon payroll taxes include federal income tax, which is withheld based on income and the information on the employee's Form W4, and FICA taxes. FICA stands for the Federal Insurance Contributions Act and pays for Social Security and Medicare. The employee share is 6.2 percent for Social Security and 1.45 percent for Medicare, and employers pay a matching share. Florida does not tax wages at the state level, but Florida has a state sales tax, and local governments may add more.\n\nEach January employers send a Form W2 showing wages and taxes withheld. Workers file an income tax return, often on Form 1040, by the filing deadline in April. If too much was withheld, the worker gets a refund, and if too little, the worker owes more. A refund is not free money but your own money returned. Keep copies of tax records.\n\nA pay stub shows gross pay, each deduction, net pay and year to date totals. Learn to read it and report mistakes. Self employed people must handle their own taxes. Rules and rates change, so use the Internal Revenue Service at IRS.gov or a trusted tax preparer for current information.\n\nYour task: (1) Tell the difference between gross pay and net pay. (2) List three payroll deductions. (3) Explain what Matthew 22:21 teaches about taxes.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Matthew 22:21 says, Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's. And Romans 13:7 says, Render therefore to all their dues. Honest taxpaying is part of good citizenship.\n\nNow watch this. Gross pay is the total earned. Net pay is what is left after deductions, also called take home pay.\n\nTaxes pay for roads, schools, emergency services and courts. Federal income tax is withheld based on your Form W4. FICA pays for Social Security and Medicare. The employee share is 6.2 percent and 1.45 percent, and the employer matches it. Florida does not tax wages at the state level, but it has a sales tax.\n\nIn January your employer sends a W2. You file a return by the April deadline. If too much was withheld, you get a refund. That is your own money returned. Keep tax records.\n\nRead your pay stub and report errors. Rates change, so check IRS.gov or a trusted tax preparer.\n\nYour task is to compare gross and net pay, list deductions and explain Matthew 22:21. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Paychecks, Taxes and Giving to Caesar$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Stewardship, Goals, Income and Taxes$j$, $j${"prompt": "Write a report of at least 250 words on the foundations of personal finance. Use complete sentences and label each part. Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein.\n\nPart 1: Explain what it means to be a steward. Tell what the parable of the talents in Matthew 25 teaches and what 1 Timothy 6:10 warns about.\nPart 2: Give three examples of needs and three of wants. Define opportunity cost and give an example from your own life.\nPart 3: Write two SMART goals, one short term and one long term, and explain how you will reach each.\nPart 4: Name four kinds of income, and describe how you would research a career using the Occupational Outlook Handbook.\nPart 5: Explain gross pay and net pay, list three deductions on a paycheck, and explain how Matthew 22:21 and Romans 13:7 apply to taxes.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Stewardship, Goals, Income and Taxes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Faithful Over a Few Things$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes something you have been given to manage, such as money, a task or a responsibility, and how you handled it, (2) explains in your own words why a steward is different from an owner, (3) explains how contentment can protect a person from the love of money, and (4) connects your answer to Psalm 24:1, Luke 12:15 or Matthew 25:21. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a young person be faithful with a small amount? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Faithful Over a Few Things$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Biblical Stewardship and the Purpose of Money$j$, $j${"questions": [{"q": "A steward is a person who:", "options": ["Owns everything outright", "Hides wealth", "Avoids all money", "Manages what belongs to another"]}, {"q": "According to Psalm 24:1, the earth and its fulness belong to:", "options": ["No one", "The rich", "The government", "The LORD"]}, {"q": "1 Timothy 6:10 warns against:", "options": ["Saving", "Working hard", "All income", "The love of money"]}, {"q": "In the parable of the talents, the servants who were praised:", "options": ["Spent it all at once", "Gave it back unused", "Buried the money", "Put the money to work"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Biblical Stewardship and the Purpose of Money$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,3}'::int[], array[$j$A steward manages for the owner.$j$,$j$God owns all things.$j$,$j$The danger is loving money.$j$,$j$Faithful use of resources was rewarded.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Biblical Stewardship and the Purpose of Money$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Needs, Wants, Goals and Choices$j$, $j${"questions": [{"q": "Something required to live, such as food and shelter, is a:", "options": ["Want", "Need", "Luxury", "Wish"]}, {"q": "The next best alternative you give up when you make a choice is called:", "options": ["Interest", "Income", "Profit", "Opportunity cost"]}, {"q": "In a SMART goal, the letter M stands for:", "options": ["Minimum", "Measurable", "Maybe", "Money"]}, {"q": "A goal that takes more than five years is:", "options": ["Daily", "Short term", "Long term", "Medium term"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Needs, Wants, Goals and Choices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,2}'::int[], array[$j$Needs are required for living.$j$,$j$Opportunity cost measures what is given up.$j$,$j$A goal should be measurable.$j$,$j$Long term goals take more than five years.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Needs, Wants, Goals and Choices$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Income, Work and Careers$j$, $j${"questions": [{"q": "Pay for each hour worked is called:", "options": ["Interest", "Salary", "Wages", "Commission"]}, {"q": "Payment based on the amount a worker sells is a:", "options": ["Tax", "Wage", "Commission", "Gift"]}, {"q": "Which source lists pay, training and job outlook for careers?", "options": ["A game guide", "A coupon book", "A weather report", "The Occupational Outlook Handbook"]}, {"q": "According to 2 Thessalonians 3:10, if any would not work:", "options": ["He should be praised", "He should be paid anyway", "He should borrow", "Neither should he eat"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Income, Work and Careers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,3}'::int[], array[$j$Wages are hourly pay.$j$,$j$Commissions depend on sales.$j$,$j$The Bureau of Labor Statistics publishes it.$j$,$j$Scripture honors work.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Income, Work and Careers$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Paychecks, Taxes and Giving to Caesar$j$, $j${"questions": [{"q": "The pay a worker takes home after deductions is called:", "options": ["Overtime", "Gross pay", "Net pay", "Principal"]}, {"q": "FICA taxes help pay for:", "options": ["Highways only", "Social Security and Medicare", "School lunches only", "Sales tax"]}, {"q": "The form an employer sends in January showing wages and withholding is the:", "options": ["W2", "Invoice", "Pay stub", "W4"]}, {"q": "When too much tax was withheld, the worker receives a:", "options": ["Refund", "Bonus", "Loan", "Penalty"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Paychecks, Taxes and Giving to Caesar$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,0}'::int[], array[$j$Net pay is gross pay minus deductions.$j$,$j$FICA funds Social Security and Medicare.$j$,$j$The W2 summarizes the year.$j$,$j$A refund returns the extra money withheld.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Paychecks, Taxes and Giving to Caesar$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Stewardship, Goals, Income and Taxes$j$, $j${"questions": [{"q": "Psalm 24:1 teaches that the earth and its fulness belong to:", "options": ["Whoever earns the most", "The government", "Banks", "The LORD"]}, {"q": "A person who manages what belongs to another is a:", "options": ["Debtor", "Steward", "Thief", "Consumer"]}, {"q": "Which is a need?", "options": ["A new game console", "Designer shoes", "A theme park ticket", "Basic food"]}, {"q": "The value of the next best choice you give up is:", "options": ["Principal", "Tax credit", "Opportunity cost", "Gross pay"]}, {"q": "Which goal is a SMART goal?", "options": ["I want to be rich", "I will save someday", "I will save 600 dollars in 12 months by setting aside 50 dollars monthly", "I hope to have money"]}, {"q": "Fixed pay for a year of work is a:", "options": ["Tip", "Salary", "Refund", "Gift"]}, {"q": "Pay before deductions is called:", "options": ["Refund", "Take home pay", "Net pay", "Gross pay"]}, {"q": "Matthew 22:21 tells believers to render unto Caesar:", "options": ["Only advice", "Nothing at all", "Their whole income", "The things that are Caesar's"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Stewardship, Goals, Income and Taxes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,3,2,2,1,3,3}'::int[], array[$j$God is the owner of all.$j$,$j$A steward manages for the owner.$j$,$j$Food is required to live.$j$,$j$That is the meaning of opportunity cost.$j$,$j$It is specific, measurable and timed.$j$,$j$A salary is a fixed annual amount.$j$,$j$Gross pay comes before deductions.$j$,$j$Honest citizens pay what is due.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Stewardship, Goals, Income and Taxes$j$ on conflict (item_id) do nothing;
